    "question_text": "A cardiac tracing displays a repetitive cycle: the PR interval progressively lengthens with each successive beat until a P wave fails to conduct and a QRS complex is completely dropped, after which the cycle repeats. What is this arrhythmia?",
    "choices": [
      "Second-degree AV block Mobitz Type I (Wenckebach phenomenon)",
      "Second-degree AV block Mobitz Type II",
      "Wolff-Parkinson-White syndrome",
      "Complete third-degree AV dissociation"
    ],
    "correct_answer": "Second-degree AV block Mobitz Type I (Wenckebach phenomenon)",
    "explanation": "Mobitz I (Wenckebach) features progressive PR prolongation until a QRS is dropped; it typically arises within the AV node and has a favorable prognosis.",
