    "exam_set": "multiple_choice",
    "question_text": "A client’s 12-lead ECG shows 3 mm of ST-segment elevation in Leads II, III, and aVF, with reciprocal ST depression in Leads I and aVL. Which myocardial wall is infarcted, and which epicardial vessel is most likely occluded?",
    "choices": [
      "Lateral wall infarction; Left Circumflex artery",
      "Inferior wall myocardial infarction; Right Coronary Artery (RCA)",
      "Anterior wall infarction; Left Anterior Descending (LAD)",
      "Septal wall infarction; Diagonal branch of LAD"
    ],
    "correct_answer": "Inferior wall myocardial infarction; Right Coronary Artery (RCA)",
    "explanation": "Leads II, III, and aVF look at the inferior wall of the heart, supplied by the RCA in 90% of people.",
